#!/usr/bin/env python3
"""Negative control on the FULL eventual image (ref_check.run): group generated by Psi over
all closed walks in all strongly connected components.  usage: ref_affine.py RULE W M"""
import sys
sys.setrecursionlimit(10**6)
from ref_check import run
rule, w, M = map(int, sys.argv[1:4])
res, (n, mask, V, idx, edges, alpha, unpack, pack) = run(rule, w, M, verbose=False)
nV = len(V)
out = [[] for _ in range(nV)]; inn = [[] for _ in range(nV)]
for (i, lab), (j, th) in edges.items(): out[i].append((j, th)); inn[j].append(i)
# Kosaraju, iterative
order = []; seen = [False]*nV
for s in range(nV):
    if seen[s]: continue
    st = [(s, 0)]; seen[s] = True
    while st:
        i, k = st.pop()
        if k < len(out[i]):
            st.append((i, k + 1)); j = out[i][k][0]
            if not seen[j]: seen[j] = True; st.append((j, 0))
        else: order.append(i)
comp = [-1]*nV; nc = 0
for s in reversed(order):
    if comp[s] >= 0: continue
    comp[s] = nc; st = [s]
    while st:
        i = st.pop()
        for j in inn[i]:
            if comp[j] < 0: comp[j] = nc; st.append(j)
    nc += 1
pot = [None]*nV; span = {0}
for s in range(nV):
    if pot[s] is not None: continue
    pot[s] = 0; st = [s]
    while st:
        i = st.pop()
        for j, th in out[i]:
            if comp[j] != comp[i]: continue
            if pot[j] is None: pot[j] = pot[i] ^ th; st.append(j)
            else:
                g = pot[i] ^ th ^ pot[j]
                if g not in span: span |= {x ^ g for x in span}
print(f"rule {rule} w={w} M={M}: eventual image {res['T']} (pred {res['pred']}), |G_w|={nV}, SCCs={nc}, "
      f"group generated by Psi over all closed walks: order {len(span)}, (l_a,l_b) part {sorted({(x>>1)&3 for x in span})}")
